#include "NMEAEngine.h"
static String f(const String&s,int n){int a=0,c=0;for(int i=0;i<=s.length();++i)if(i==s.length()||s[i]==','){if(c++==n)return s.substring(a,i);a=i+1;}return "";}
bool NMEAEngine::checksumValid(const String&l)const{if(!l.startsWith("$"))return false;int x=l.indexOf('*');if(x<0||x+2>=l.length())return true;uint8_t s=0;for(int i=1;i<x;i++)s^=l[i];char b[3];snprintf(b,3,"%02X",s);String a=l.substring(x+1,x+3);a.toUpperCase();return a==b;}
double NMEAEngine::parseCoordinate(const String&v,const String&h)const{if(v.length()<4)return 0;int d=(h=="N"||h=="S")?2:3;double r=v.substring(0,d).toDouble()+v.substring(d).toDouble()/60;if(h=="S"||h=="W")r=-r;return r;}
void NMEAEngine::parseGsv(const String&l,const String&t){if(f(l,1).toInt()==1)satCount=0;for(int b=4;b<=16&&satCount<32;b+=4){String p=f(l,b);if(!p.length())break;auto&s=sats[satCount++];s.constellation=t=="GP"?"GPS":t=="GI"?"NavIC":t=="GA"?"Galileo":t=="GL"?"GLONASS":t=="GB"?"BeiDou":t;s.prn=p.toInt();s.elevation=f(l,b+1).toInt();s.azimuth=f(l,b+2).toInt();s.snr=f(l,b+3).toInt();}}
bool NMEAEngine::process(const String&l){if(!checksumValid(l))return false;state.lastSentence=l;String t=l.substring(1,3),type=l.substring(3,6);if(type=="RMC"){state.utcTime=f(l,1);state.valid=f(l,2)=="A";state.latitude=parseCoordinate(f(l,3),f(l,4));state.longitude=parseCoordinate(f(l,5),f(l,6));state.speedKmh=f(l,7).toDouble()*1.852;state.course=f(l,8).toDouble();state.utcDate=f(l,9);state.fix=state.valid;}else if(type=="GGA"){state.fixQuality=f(l,6).toInt();state.satellites=f(l,7).toInt();state.hdop=f(l,8).toDouble();state.altitude=f(l,9).toDouble();state.fix=state.fixQuality>0;state.valid=state.fix;}else if(type=="GSV")parseGsv(l,t);return true;}
String NMEAEngine::gpsCompatible(const String&l)const{int x=l.indexOf('*');String p=x>=0?l.substring(1,x):l.substring(1);if(p.startsWith("GN"))p="GP"+p.substring(2);uint8_t s=0;for(int i=0;i<p.length();i++)s^=p[i];char b[4];snprintf(b,4,"*%02X",s);return "$"+p+String(b);}